namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Code = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30 AM-12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an expert in algorithm design with research focus on graph algorithms. He previously worked at Google Research.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, Code = "CS310", Title = "Database Systems", Description = "Design and implementation of relational database systems. Covers SQL, normalization, transaction processing, and query optimization.", Credits = 3, Schedule = "Mon/Wed 2:00-3:20 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez specializes in distributed database systems and has contributed to several open-source database projects.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 2, Code = "MATH101", Title = "Calculus I", Description = "Introduction to differential calculus. Topics include limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, Code = "MATH201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and systems of linear equations.", Credits = 3, Schedule = "Tue/Thu 1:00-2:20 PM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang's research spans computational linear algebra and numerical methods. She holds multiple teaching excellence awards.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM + Lab Thu 2:00-4:00 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with a background in particle physics at CERN. He emphasizes hands-on learning.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS202", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00-10:20 AM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang researches quantum electrodynamics and has authored two widely-used physics textbooks.", IsFeatured = false },
            new() { Id = 8, DepartmentId = 4, Code = "ENG101", Title = "Composition and Rhetoric", Description = "Develop effective writing skills through essays, research papers, and peer review. Focus on argumentation and clarity.", Credits = 3, Schedule = "Mon/Wed 9:00-10:20 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing coach who has helped thousands of students improve their academic writing.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 4, Code = "ENG220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examines major authors, movements, and themes.", Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:20 PM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks is a specialist in 20th-century American fiction and has published critical analyses of works by Faulkner, Morrison, and DeLillo.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 5, Code = "HIST101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural developments, and historical events from antiquity to the early modern period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian specializing in ancient Mediterranean civilizations with fieldwork experience in Greece and Egypt.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 5, Code = "HIST250", Title = "Modern European History", Description = "Europe from the Enlightenment to the present day. Covers revolutions, world wars, and the formation of the European Union.", Credits = 3, Schedule = "Tue/Thu 2:30-3:50 PM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois is a Franco-American historian with expertise in modern European political history and transatlantic relations.", IsFeatured = false }
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

